               "types" : [ "postal_code" ]
            }
         ],
         "formatted_address" : "1600 Amphitheatre Parkway, Mountain View, CA 94043, USA",
         "geometry" : {
            "location" : {
               "lat" : 37.4224764,
               "lng" : -122.0842499
            },
            "location_type" : "ROOFTOP",
            "viewport" : {
               "northeast" : {
                  "lat" : 37.4238253802915,
                  "lng" : -122.0829009197085
               },
               "southwest" : {
                  "lat" : 37.4211274197085,
                  "lng" : -122.0855988802915
               }
            }
         },
         "place_id" : "ChIJj61dQgK6j4AR4Z7x8YfXc3I",
         "types" : [ "street_address" ]
      }
   ],
   "status" : "OK"
}
```

> **What you’ll see:**  
> * `formatted_address` gives the full street address.  
> * `geometry.location` confirms the same latitude/longitude you supplied.  
> * `place_id` is a unique identifier for that location.

---

## 3. Quick Python snippet (using `requests`)

```python
import requests

API_KEY = "YOUR_API_KEY"
lat, lng = 37.4224764, -122.0842499
url = f"https://maps.googleapis.com/maps/api/geocode/json?latlng={lat},{lng}&key={API_KEY}"

resp = requests.get(url)
data = resp.json()

if data["status"] == "OK":
    print("Formatted address:", data["results"][0]["formatted_address"])
else:
    print("Error:", data["status"])
```

---

### TL;DR

* The coordinates you gave are **already** the latitude/longitude pair.  
* To confirm or get the address, hit the reverse‑geocoding endpoint shown above.  
* The API will return the same coordinates plus a formatted address (e.g., “1600 Amphitheatre Parkway, Mountain View, CA 94043, USA”).

